INSERT INTO dbo.MonitoringProgramCategory (MonitoringProgramCategoryID, MonitoringProgramCategoryName, Folder, ThemeColor, SortOrder, Blurb, CategoryDescription, IconName) VALUES (3, N'Recreation', N'recreation', N'#F78814', 30, N'Recreation capacity, access, and visitor experience.', N'Preserve and enhance a high-quality recreational experience. Preserve undeveloped shorezone and other natural areas and maintain a fair share of recreational capacity for the general public.', N'Recreation');
