INSERT INTO dbo.MonitoringProgram (MonitoringProgramID, MonitoringProgramName, MonitoringProgramCategoryID, MonitoringProgramDescription, MonitoringApproach, IsFeatured, Template, DashboardConfig) VALUES (26, N'Carbon Monoxide (CO)', 1, NULL, N'Between 1983 and 1998, CO was monitored at the Horizon Hotel in Stateline, Nevada. In 1999, the monitoring site was relocated to Harvey’s Resort parking garage in Stateline, Nevada. The site is located to monitor the highest CO concentrations in the Lake Tahoe Basin because historically this area received the highest traffic volume, and is intended to be representative of both the California and Nevada sides of the South Shore Resort District. NDEP successfully petitioned the EPA to remove this monitoring site on June 30, 2012 because of the continued compliance with established CO concentration standards. CARB provided TRPA with a CO monitor which was installed on the roof of the TRPA building in Stateline, NV in 2013.', 0, N'charts', N'{"measures":[{"title":"Carbon monoxide by station","sub":"Yearly carbon monoxide (CO) statistic at each monitoring station, in parts per million. Choose a statistic.","layer":46,"where":"Pollutant = ''CO''","x":"Year","y":"Value","yLabel":"CO (ppm)","seriesBy":"Site","seriesLabel":"Station","pick":"Indicator","pickLabel":"Statistic","pickDefault":"CO - HIGH 8 HR","standard":{"field":"Threshold_Value"},"span":"span-12"},{"title":"Daily carbon monoxide by station","sub":"Daily carbon monoxide (CO) values at each station from the daily monitoring record, in the units named in each statistic. Choose a statistic.","layer":17,"where":"variable LIKE ''CO%''","x":"date","xType":"date","xLabel":"Date","y":"value","yName":"CO","yLabel":"CO","seriesBy":"id","seriesLabel":"Station","seriesNames":{"STL":"Stateline","TC":"Tahoe City","IV":"Incline Village","SLT":"South Lake Tahoe","BSP":"DL Bliss State Park","LTC":"Lake Tahoe Community College"},"pick":"variable","pickLabel":"Statistic","span":"span-12"}],"sitesLayer":{"layer":16,"name":"name","code":"id","active":"Active_2023","unit":"station"},"sitesPerYear":{"layer":46,"year":"Year","site":"Site","where":"Pollutant = ''CO''","unit":"station"}}');
